from taf.cloud.lcmaas.schemas.schema_base import SchemaObject, SchemaField


class HelmChartInfo(SchemaObject):
    chart_name = SchemaField(name='name', not_null=True)
    chart_version = SchemaField(name='version', not_null=True)
    api_version = SchemaField(name='api_version', not_null=True)
    app_version = SchemaField(name='app_version', not_null=True)
    main_chart = SchemaField(name='main_chart')
    file = SchemaField(name='file')

    def __init__(self, chart_name, chart_version, api_version, app_version, main_chart, file):
        self.chart_name = chart_name
        self.chart_version = chart_version
        self.api_version = api_version
        self.app_version = app_version
        self.main_chart = main_chart
        self.file = file

        super(HelmChartInfo, self).__init__()


class CnfPkgInfoV1(SchemaObject):
    cnf_pkg_name = SchemaField(name="name", not_null=True)
    status = SchemaField(name="status", not_null=True)
    cnf_pkg_url = SchemaField(name="url", not_null=True)
    chart_info = SchemaField(name="charts", klass=HelmChartInfo, many=True)
    progress = SchemaField(name='progress', not_null=True)

    def __init__(self, cnf_pkg_name, status, cnf_pkg_url, chart_info, progress):
        self.cnf_pkg_name = cnf_pkg_name
        self.status = status
        self.cnf_pkg_url = cnf_pkg_url
        self.chart_info = chart_info
        self.progress = progress

        super(CnfPkgInfoV1, self).__init__()
